// Généré par scripts/build_exercises.py — source : free-exercise-db (domaine public)
export const LIB = {"Ab_Crunch_Machine": {"name": "Ab Crunch Machine", "equipment": "machine", "primary": ["abdominals"], "instructions": ["Select a light resistance and sit down on the ab machine placing your feet under the pads provided and grabbing the top handles. Your arms should be bent at a 90 degree angle as you rest the triceps on the pads provided. This will be your starting position.", "At the same time, begin to lift the legs up as you crunch your upper torso. Breathe out as you perform this movement. Tip: Be sure to use a slow and controlled motion. Concentrate on using your abs to move the weight while relaxing your legs and feet.", "After a second pause, slowly return to the starting position as you breathe in.", "Repeat the movement for the prescribed amount of repetitions."], "images": ["img/Ab_Crunch_Machine/0.webp", "img/Ab_Crunch_Machine/1.webp"]}, "Ab_Roller": {"name": "Ab Roller", "equipment": "other", "primary": ["abdominals"], "instructions": ["Hold the Ab Roller with both hands and kneel on the floor.", "Now place the ab roller on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position.", "Slowly roll the ab roller straight forward, stretching your body into a straight position. Tip: Go down as far as you can without touching the floor with your body. Breathe in during this portion of the movement.", "After a pause at the stretched position, start pulling yourself back to the starting position as you breathe out. Tip: Go slowly and keep your abs tight at all times."], "images": ["img/Ab_Roller/0.webp", "img/Ab_Roller/1.webp"]}, "Alternate_Incline_Dumbbell_Curl": {"name": "Alternate Incline Dumbbell Curl", "equipment": "dumbbell", "primary": ["biceps"], "instructions": ["Sit down on an incline bench with a dumbbell in each hand being held at arms length. Tip: Keep the elbows close to the torso.This will be your starting position.", "While holding the upper arm stationary, curl the right weight forward while contracting the biceps as you breathe out. As you do so, rotate the hand so that the palm is facing up. Continue the movement until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move.", "Slowly begin to bring the dumbbell back to starting position as your breathe in.", "Repeat the movement with the left hand. This equals one repetition.", "Continue alternating in this manner for the recommended amount of repetitions."], "images": ["img/Alternate_Incline_Dumbbell_Curl/0.webp", "img/Alternate_Incline_Dumbbell_Curl/1.webp"]}, "Arnold_Dumbbell_Press": {"name": "Arnold Dumbbell Press", "equipment": "dumbbell", "primary": ["shoulders"], "instructions": ["Sit on an exercise bench with back support and hold two dumbbells in front of you at about upper chest level with your palms facing your body and your elbows bent. Tip: Your arms should be next to your torso. The starting position should look like the contracted portion of a dumbbell curl.", "Now to perform the movement, raise the dumbbells as you rotate the palms of your hands until they are facing forward.", "Continue lifting the dumbbells until your arms are extended above you in straight arm position. Breathe out as you perform this portion of the movement.", "After a second pause at the top, begin to lower the dumbbells to the original position by rotating the palms of your hands towards you. Tip: The left arm will be rotated in a counter clockwise manner while the right one will be rotated clockwise. Breathe in as you perform this portion of the movement.", "Repeat for the recommended amount of repetitions."], "images": ["img/Arnold_Dumbbell_Press/0.webp", "img/Arnold_Dumbbell_Press/1.webp"]}, "Ball_Leg_Curl": {"name": "Ball Leg Curl", "equipment": "exercise ball", "primary": ["hamstrings"], "instructions": ["Begin on the floor laying on your back with your feet on top of the ball.", "Position the ball so that when your legs are extended your ankles are on top of the ball. This will be your starting position.", "Raise your hips off of the ground, keeping your weight on the shoulder blades and your feet.", "Flex the knees, pulling the ball as close to you as you can, contracting the hamstrings.", "After a brief pause, return to the starting position."], "images": ["img/Ball_Leg_Curl/0.webp", "img/Ball_Leg_Curl/1.webp"]}, "Band_Assisted_Pull-Up": {"name": "Band Assisted Pull-Up", "equipment": "other", "primary": ["lats"], "instructions": ["Choke the band around the center of the pullup bar. You can use different bands to provide varying levels of assistance.", "Pull the end of the band down, and place one bent knee into the loop, ensuring it won't slip out. Take a medium to wide grip on the bar. This will be your starting position.", "Pull yourself upward by contracting the lats as you flex the elbow. The elbow should be driven to your side. Pull to the front, attempting to get your chin over the bar. Avoid swinging or jerking movements.", "After a brief pause, return to the starting position."], "images": ["img/Band_Assisted_Pull-Up/0.webp", "img/Band_Assisted_Pull-Up/1.webp"]}, "Barbell_Bench_Press_-_Medium_Grip": {"name": "Barbell Bench Press - Medium Grip", "equipment": "barbell", "primary": ["chest"], "instructions": ["Lie back on a flat bench. Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.", "From the starting position, breathe in and begin coming down slowly until the bar touches your middle chest.", "After a brief pause, push the bar back to the starting position as you breathe out. Focus on pushing the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position at the top of the motion, hold for a second and then start coming down slowly again. Tip: Ideally, lowering the weight should take about twice as long as raising it.", "Repeat the movement for the prescribed amount of repetitions.", "When you are done, place the bar back in the rack."], "images": ["img/Barbell_Bench_Press_-_Medium_Grip/0.webp", "img/Barbell_Bench_Press_-_Medium_Grip/1.webp"]}, "Barbell_Full_Squat": {"name": "Barbell Full Squat", "equipment": "barbell", "primary": ["quadriceps"], "instructions": ["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just above shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.", "Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.", "Step away from the rack and position your legs using a shoulder-width medium stance with the toes slightly pointed out. Keep your head up at all times and maintain a straight back. This will be your starting position.", "Begin to slowly lower the bar by bending the knees and sitting back with your hips as you maintain a straight posture with the head up. Continue down until your hamstrings are on your calves. Inhale as you perform this portion of the movement.", "Begin to raise the bar as you exhale by pushing the floor with the heel or middle of your foot as you straighten the legs and extend the hips to go back to the starting position.", "Repeat for the recommended amount of repetitions."], "images": ["img/Barbell_Full_Squat/0.webp", "img/Barbell_Full_Squat/1.webp"]}, "Barbell_Glute_Bridge": {"name": "Barbell Glute Bridge", "equipment": "barbell", "primary": ["glutes"], "instructions": ["Begin seated on the ground with a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise. Roll the bar so that it is directly above your hips, and lay down flat on the floor.", "Begin the movement by driving through with your heels, extending your hips vertically through the bar. Your weight should be supported by your upper back and the heels of your feet.", "Extend as far as possible, then reverse the motion to return to the starting position."], "images": ["img/Barbell_Glute_Bridge/0.webp", "img/Barbell_Glute_Bridge/1.webp"]}, "Barbell_Hip_Thrust": {"name": "Barbell Hip Thrust", "equipment": "barbell", "primary": ["glutes"], "instructions": ["Begin seated on the ground with a bench directly behind you. Have a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise.", "Roll the bar so that it is directly above your hips, and lean back against the bench so that your shoulder blades are near the top of it.", "Begin the movement by driving through your feet, extending your hips vertically through the bar. Your weight should be supported by your shoulder blades and your feet. Extend as far as possible, then reverse the motion to return to the starting position."], "images": ["img/Barbell_Hip_Thrust/0.webp", "img/Barbell_Hip_Thrust/1.webp"]}, "Barbell_Seated_Calf_Raise": {"name": "Barbell Seated Calf Raise", "equipment": "barbell", "primary": ["calves"], "instructions": ["Place a block about 12 inches in front of a flat bench.", "Sit on the bench and place the ball of your feet on the block.", "Have someone place a barbell over your upper thighs about 3 inches above your knees and hold it there. This will be your starting position.", "Raise up on your toes as high as possible as you squeeze the calves and as you breathe out.", "After a second contraction, slowly go back to the starting position. Tip: To get maximum benefit stretch your calves as far as you can.", "Repeat for the recommended amount of repetitions."], "images": ["img/Barbell_Seated_Calf_Raise/0.webp", "img/Barbell_Seated_Calf_Raise/1.webp"]}, "Bent_Over_Two-Dumbbell_Row": {"name": "Bent Over Two-Dumbbell Row", "equipment": "dumbbell", "primary": ["middle back"], "instructions": ["With a dumbbell in each hand (palms facing your torso), bend your knees slightly and bring your torso forward by bending at the waist; as you bend make sure to keep your back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The weights should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.", "While keeping the torso stationary, lift the dumbbells to your side (as you breathe out), keeping the elbows close to the body (do not exert any force with the forearm other than holding the weights). On the top contracted position, squeeze the back muscles and hold for a second.", "Slowly lower the weight again to the starting position as you inhale.", "Repeat for the recommended amount of repetitions."], "images": ["img/Bent_Over_Two-Dumbbell_Row/0.webp", "img/Bent_Over_Two-Dumbbell_Row/1.webp"]}, "Butterfly": {"name": "Butterfly", "equipment": "machine", "primary": ["chest"], "instructions": ["Sit on the machine with your back flat on the pad.", "Take hold of the handles. Tip: Your upper arms should be positioned parallel to the floor; adjust the machine accordingly. This will be your starting position.", "Push the handles together slowly as you squeeze your chest in the middle. Breathe out during this part of the motion and hold the contraction for a second.", "Return back to the starting position slowly as you inhale until your chest muscles are fully stretched.", "Repeat for the recommended amount of repetitions."], "images": ["img/Butterfly/0.webp", "img/Butterfly/1.webp"]}, "Cable_Crossover": {"name": "Cable Crossover", "equipment": "cable", "primary": ["chest"], "instructions": ["To get yourself into the starting position, place the pulleys on a high position (above your head), select the resistance to be used and hold the pulleys in each hand.", "Step forward in front of an imaginary straight line between both pulleys while pulling your arms together in front of you. Your torso should have a small forward bend from the waist. This will be your starting position.", "With a slight bend on your elbows in order to prevent stress at the biceps tendon, extend your arms to the side (straight out at both sides) in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms and torso should remain stationary; the movement should only occur at the shoulder joint.", "Return your arms back to the starting position as you breathe out. Make sure to use the same arc of motion used to lower the weights.", "Hold for a second at the starting position and repeat the movement for the prescribed amount of repetitions."], "images": ["img/Cable_Crossover/0.webp", "img/Cable_Crossover/1.webp"]}, "Cable_Crunch": {"name": "Cable Crunch", "equipment": "cable", "primary": ["abdominals"], "instructions": ["Kneel below a high pulley that contains a rope attachment.", "Grasp cable rope attachment and lower the rope until your hands are placed next to your face.", "Flex your hips slightly and allow the weight to hyperextend the lower back. This will be your starting position.", "With the hips stationary, flex the waist as you contract the abs so that the elbows travel towards the middle of the thighs. Exhale as you perform this portion of the movement and hold the contraction for a second.", "Slowly return to the starting position as you inhale. Tip: Make sure that you keep constant tension on the abs throughout the movement. Also, do not choose a weight so heavy that the lower back handles the brunt of the work.", "Repeat for the recommended amount of repetitions."], "images": ["img/Cable_Crunch/0.webp", "img/Cable_Crunch/1.webp"]}, "Cable_Lying_Triceps_Extension": {"name": "Cable Lying Triceps Extension", "equipment": "cable", "primary": ["triceps"], "instructions": ["Lie on a flat bench and grasp the straight bar attachment of a low pulley with a narrow overhand grip. Tip: The easiest way to do this is to have someone hand you the bar as you lay down.", "With your arms extended, position the bar over your torso. Your arms and your torso should create a 90-degree angle. This will be your starting position.", "Lower the bar by bending at the elbow while keeping the upper arms stationary and elbows in. Go down until the bar lightly touches your forehead. Breathe in as you perform this portion of the movement.", "Flex the triceps as you lift the bar back to its starting position. Exhale as you perform this portion of the movement.", "Hold for a second at the contracted position and repeat for the recommended amount of repetitions."], "images": ["img/Cable_Lying_Triceps_Extension/0.webp", "img/Cable_Lying_Triceps_Extension/1.webp"]}, "Cable_Preacher_Curl": {"name": "Cable Preacher Curl", "equipment": "cable", "primary": ["biceps"], "instructions": ["Place a preacher bench about 2 feet in front of a pulley machine.", "Attach a straight bar to the low pulley.", "Sit at the preacher bench with your elbow and upper arms firmly on top of the bench pad and have someone hand you the bar from the low pulley.", "Grab the bar and fully extend your arms on top of the preacher bench pad. This will be your starting position.", "Now start pilling the weight up towards your shoulders and squeeze the biceps hard at the top of the movement. Exhale as you perform this motion. Also, hold for a second at the top.", "Now slowly lower the weight to the starting position.", "Repeat for the recommended amount of repetitions."], "images": ["img/Cable_Preacher_Curl/0.webp", "img/Cable_Preacher_Curl/1.webp"]}, "Cable_Rear_Delt_Fly": {"name": "Cable Rear Delt Fly", "equipment": "cable", "primary": ["shoulders"], "instructions": ["Adjust the pulleys to the appropriate height and adjust the weight. The pulleys should be above your head.", "Grab the left pulley with your right hand and the right pulley with your left hand, crossing them in front of you. This will be your starting position.", "Initiate the movement by moving your arms back and outward, keeping your arms straight as you execute the movement.", "Pause at the end of the motion before returning the handles to the start position."], "images": ["img/Cable_Rear_Delt_Fly/0.webp", "img/Cable_Rear_Delt_Fly/1.webp"]}, "Cable_Rope_Overhead_Triceps_Extension": {"name": "Cable Rope Overhead Triceps Extension", "equipment": "cable", "primary": ["triceps"], "instructions": ["Attach a rope to the bottom pulley of the pulley machine.", "Grasping the rope with both hands, extend your arms with your hands directly above your head using a neutral grip (palms facing each other). Your elbows should be in close to your head and the arms should be perpendicular to the floor with the knuckles aimed at the ceiling. This will be your starting position.", "Slowly lower the rope behind your head as you hold the upper arms stationary. Inhale as you perform this movement and pause when your triceps are fully stretched.", "Return to the starting position by flexing your triceps as you breathe out.", "Repeat for the recommended amount of repetitions."], "images": ["img/Cable_Rope_Overhead_Triceps_Extension/0.webp", "img/Cable_Rope_Overhead_Triceps_Extension/1.webp"]}, "Cable_Rope_Rear-Delt_Rows": {"name": "Cable Rope Rear-Delt Rows", "equipment": "cable", "primary": ["shoulders"], "instructions": ["Sit in the same position on a low pulley row station as you would if you were doing seated cable rows for the back.", "Attach a rope to the pulley and grasp it with an overhand grip. Your arms should be extended and parallel to the floor with the elbows flared out.", "Keep your lower back upright and slide your hips back so that your knees are slightly bent. This will be your starting position.", "Pull the cable attachment towards your upper chest, just below the neck, as you keep your elbows up and out to the sides. Continue this motion as you exhale until the elbows travel slightly behind the back. Tip: Keep your upper arms horizontal, perpendicular to the torso and parallel to the floor throughout the motion.", "Go back to the initial position where the arms are extended and the shoulders are stretched forward. Inhale as you perform this portion of the movement.", "Repeat for the recommended amount of repetitions."], "images": ["img/Cable_Rope_Rear-Delt_Rows/0.webp", "img/Cable_Rope_Rear-Delt_Rows/1.webp"]}, "Cable_Seated_Lateral_Raise": {"name": "Cable Seated Lateral Raise", "equipment": "cable", "primary": ["shoulders"], "instructions": ["Stand in the middle of two low pulleys that are opposite to each other and place a flat bench right behind you (in perpendicular fashion to you; the narrow edge of the bench should be the one behind you). Select the weight to be used on each pulley.", "Now sit at the edge of the flat bench behind you with your feet placed in front of your knees.", "Bend forward while keeping your back flat and rest your torso on the thighs.", "Have someone give you the single handles attached to the pulleys. Grasp the left pulley with the right hand and the right pulley with the left after you select your weight. The pulleys should run under your knees and your arms will be extended with palms facing each other and a slight bend at the elbows. This will be the starting position.", "While keeping the arms stationary, raise the upper arms to the sides until they are parallel to the floor and at shoulder height. Exhale during the execution of this movement and hold the contraction for a second.", "Slowly lower your arms to the starting position as you inhale.", "Repeat for the recommended amount of repetitions. Tip: Maintain upper arms perpendicular to torso and a fixed elbow position (10 degree to 30 degree angle) throughout exercise."], "images": ["img/Cable_Seated_Lateral_Raise/0.webp", "img/Cable_Seated_Lateral_Raise/1.webp"]}, "Calf_Press_On_The_Leg_Press_Machine": {"name": "Calf Press On The Leg Press Machine", "equipment": "machine", "primary": ["calves"], "instructions": ["Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance.", "Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you without locking your knees. (Note: In some leg press units you can leave the safety bars on for increased safety. If your leg press unit allows for this, then this is the preferred method of performing the exercise.) Your torso and the legs should make perfect 90-degree angle. Now carefully place your toes and balls of your feet on the lower portion of the platform with the heels extending off. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. This will be your starting position.", "Press on the platform by raising your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.", "Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.", "Repeat for the recommended amount of repetitions."], "images": ["img/Calf_Press_On_The_Leg_Press_Machine/0.webp", "img/Calf_Press_On_The_Leg_Press_Machine/1.webp"]}, "Chin-Up": {"name": "Chin-Up", "equipment": "body only", "primary": ["lats"], "instructions": ["Grab the pull-up bar with the palms facing your torso and a grip closer than the shoulder width.", "As you have both arms extended in front of you holding the bar at the chosen grip width, keep your torso as straight as possible while creating a curvature on your lower back and sticking your chest out. This is your starting position. Tip: Keeping the torso as straight as possible maximizes biceps stimulation while minimizing back involvement.", "As you breathe out, pull your torso up until your head is around the level of the pull-up bar. Concentrate on using the biceps muscles in order to perform the movement. Keep the elbows close to your body. Tip: The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.", "After a second of squeezing the biceps in the contracted position, slowly lower your torso back to the starting position; when your arms are fully extended. Breathe in as you perform this portion of the movement.", "Repeat this motion for the prescribed amount of repetitions."], "images": ["img/Chin-Up/0.webp", "img/Chin-Up/1.webp"]}, "Close-Grip_Front_Lat_Pulldown": {"name": "Close-Grip Front Lat Pulldown", "equipment": "cable", "primary": ["lats"], "instructions": ["Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.", "Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.", "As you have both arms extended in front of you - while holding the bar at the chosen grip width - bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.", "As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary (only the arms should move). The forearms should do no other work except for holding the bar; therefore do not try to pull the bar down using the forearms.", "After a second in the contracted position, while squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.", "6. Repeat this motion for the prescribed amount of repetitions."], "images": ["img/Close-Grip_Front_Lat_Pulldown/0.webp", "img/Close-Grip_Front_Lat_Pulldown/1.webp"]}, "Dip_Machine": {"name": "Dip Machine", "equipment": "machine", "primary": ["triceps"], "instructions": ["Sit securely in a dip machine, select the weight and firmly grasp the handles.", "Now keep your elbows in at your sides in order to place emphasis on the triceps. The elbows should be bent at a 90 degree angle.", "As you contract the triceps, extend your arms downwards as you exhale. Tip: At the bottom of the movement, focus on keeping a little bend in your arms to keep tension on the triceps muscle.", "Now slowly let your arms come back up to the starting position as you inhale.", "Repeat for the recommended amount of repetitions."], "images": ["img/Dip_Machine/0.webp", "img/Dip_Machine/1.webp"]}, "Dips_-_Chest_Version": {"name": "Dips - Chest Version", "equipment": "other", "primary": ["chest"], "instructions": ["For this exercise you will need access to parallel bars. To get yourself into the starting position, hold your body at arms length (arms locked) above the bars.", "While breathing in, lower yourself slowly with your torso leaning forward around 30 degrees or so and your elbows flared out slightly until you feel a slight stretch in the chest.", "Once you feel the stretch, use your chest to bring your body back to the starting position as you breathe out. Tip: Remember to squeeze the chest at the top of the movement for a second.", "Repeat the movement for the prescribed amount of repetitions."], "images": ["img/Dips_-_Chest_Version/0.webp", "img/Dips_-_Chest_Version/1.webp"]}, "Donkey_Calf_Raises": {"name": "Donkey Calf Raises", "equipment": "other", "primary": ["calves"], "instructions": ["For this exercise you will need access to a donkey calf raise machine. Start by positioning your lower back and hips under the padded lever provided. The tailbone area should be the one making contact with the pad.", "Place both of your arms on the side handles and place the balls of your feet on the calf block with the heels extending off. Align the toes forward, inward or outward, depending on the area you wish to target, and straighten the knees without locking them. This will be your starting position.", "Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.", "Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.", "Repeat for the recommended amount of repetitions."], "images": ["img/Donkey_Calf_Raises/0.webp", "img/Donkey_Calf_Raises/1.webp"]}, "Dumbbell_Flyes": {"name": "Dumbbell Flyes", "equipment": "dumbbell", "primary": ["chest"], "instructions": ["Lie down on a flat bench with a dumbbell on each hand resting on top of your thighs. The palms of your hand will be facing each other.", "Then using your thighs to help raise the dumbbells, lift the dumbbells one at a time so you can hold them in front of you at shoulder width with the palms of your hands facing each other. Raise the dumbbells up like you're pressing them, but stop and hold just before you lock out. This will be your starting position.", "With a slight bend on your elbows in order to prevent stress at the biceps tendon, lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary; the movement should only occur at the shoulder joint.", "Return your arms back to the starting position as you squeeze your chest muscles and breathe out. Tip: Make sure to use the same arc of motion used to lower the weights.", "Hold for a second at the contracted position and repeat the movement for the prescribed amount of repetitions."], "images": ["img/Dumbbell_Flyes/0.webp", "img/Dumbbell_Flyes/1.webp"]}, "Dumbbell_One-Arm_Triceps_Extension": {"name": "Dumbbell One-Arm Triceps Extension", "equipment": "dumbbell", "primary": ["triceps"], "instructions": ["Grab a dumbbell and either sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs or stand up straight.", "Clean the dumbbell up to bring it to shoulder height and then extend the arm over your head so that the whole arm is perpendicular to the floor and next to your head. The dumbbell should be on top of you. The other hand can be kept fully extended to the side, by the waist, supporting the upper arm that has the dumbbell or grabbing a fixed surface.", "Rotate the wrist so that the palm of your hand is facing forward and the pinkie is facing the ceiling. This will be your starting position.", "Slowly lower the dumbbell behind your head as you hold the upper arm stationary. Inhale as you perform this movement and pause when your triceps are fully stretched.", "Return to the starting position by flexing your triceps as you breathe out. Tip: It is imperative that only the forearm moves. The upper arm should remain at all times stationary next to your head.", "Repeat for the recommended amount of repetitions and switch arms."], "images": ["img/Dumbbell_One-Arm_Triceps_Extension/0.webp", "img/Dumbbell_One-Arm_Triceps_Extension/1.webp"]}, "Dumbbell_Rear_Lunge": {"name": "Dumbbell Rear Lunge", "equipment": "dumbbell", "primary": ["quadriceps"], "instructions": ["Stand with your torso upright holding two dumbbells in your hands by your sides. This will be your starting position.", "Step backward with your right leg around two feet or so from the left foot and lower your upper body down, while keeping the torso upright and maintaining balance. Inhale as you go down. Tip: As in the other exercises, do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. Make sure that you keep your front shin perpendicular to the ground. Keep the torso upright during the lunge; flexible hip flexors are important. A long lunge emphasizes the Gluteus Maximus; a short lunge emphasizes Quadriceps.", "Push up and go back to the starting position as you exhale. Tip: Use the ball of your feet to push in order to accentuate the quadriceps. To focus on the glutes, press with your heels.", "Now repeat with the opposite leg."], "images": ["img/Dumbbell_Rear_Lunge/0.webp", "img/Dumbbell_Rear_Lunge/1.webp"]}, "EZ-Bar_Skullcrusher": {"name": "EZ-Bar Skullcrusher", "equipment": "e-z curl bar", "primary": ["triceps"], "instructions": ["Using a close grip, lift the EZ bar and hold it with your elbows in as you lie on the bench. Your arms should be perpendicular to the floor. This will be your starting position.", "Keeping the upper arms stationary, lower the bar by allowing the elbows to flex. Inhale as you perform this portion of the movement. Pause once the bar is directly above the forehead.", "Lift the bar back to the starting position by extending the elbow and exhaling.", "Repeat."], "images": ["img/EZ-Bar_Skullcrusher/0.webp", "img/EZ-Bar_Skullcrusher/1.webp"]}, "Face_Pull": {"name": "Face Pull", "equipment": "cable", "primary": ["shoulders"], "instructions": ["Facing a high pulley with a rope or dual handles attached, pull the weight directly towards your face, separating your hands as you do so. Keep your upper arms parallel to the ground."], "images": ["img/Face_Pull/0.webp", "img/Face_Pull/1.webp"]}, "Good_Morning": {"name": "Good Morning", "equipment": "barbell", "primary": ["hamstrings"], "instructions": ["Begin with a bar on a rack at shoulder height. Rack the bar across the rear of your shoulders as you would a power squat, not on top of your shoulders. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Step back from the rack.", "Begin by bending at the hips, moving them back as you bend over to near parallel. Keep your back arched and your cervical spine in proper alignment.", "Reverse the motion by extending through the hips with your glutes and hamstrings. Continue until you have returned to the starting position."], "images": ["img/Good_Morning/0.webp", "img/Good_Morning/1.webp"]}, "Hack_Squat": {"name": "Hack Squat", "equipment": "machine", "primary": ["quadriceps"], "instructions": ["Place the back of your torso against the back pad of the machine and hook your shoulders under the shoulder pads provided.", "Position your legs in the platform using a shoulder width medium stance with the toes slightly pointed out. Tip: Keep your head up at all times and also maintain the back on the pad at all times.", "Place your arms on the side handles of the machine and disengage the safety bars (which on most designs is done by moving the side handles from a facing front position to a diagonal position).", "Now straighten your legs without locking the knees. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).", "Begin to slowly lower the unit by bending the knees as you maintain a straight posture with the head up (back on the pad at all times). Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.", "Begin to raise the unit as you exhale by pushing the floor with mainly with the heel of your foot as you straighten the legs again and go back to the starting position.", "Repeat for the recommended amount of repetitions."], "images": ["img/Hack_Squat/0.webp", "img/Hack_Squat/1.webp"]}, "Hammer_Grip_Incline_DB_Bench_Press": {"name": "Hammer Grip Incline DB Bench Press", "equipment": "dumbbell", "primary": ["chest"], "instructions": ["Lie back on an incline bench with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.", "By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them at shoulder width.", "Once at shoulder width, keep the palms of your hands with a neutral grip (palms facing each other). Keep your elbows flared out with the upper arms in line with the shoulders (perpendicular to the torso) and the elbows bent creating a 90-degree angle between the upper arm and the forearm. This will be your starting position.", "Now bring down the weights slowly to your side as you breathe in. Keep full control of the dumbbells at all times.", "As you breathe out, push the dumbbells up using your pectoral muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up.", "Repeat the movement for the prescribed amount of repetitions.", "When you are done, place the dumbbells back in your thighs and then on the floor. This is the safest manner to dispose of the dumbbells."], "images": ["img/Hammer_Grip_Incline_DB_Bench_Press/0.webp", "img/Hammer_Grip_Incline_DB_Bench_Press/1.webp"]}, "Hanging_Leg_Raise": {"name": "Hanging Leg Raise", "equipment": "body only", "primary": ["abdominals"], "instructions": ["Hang from a chin-up bar with both arms extended at arms length in top of you using either a wide grip or a medium grip. The legs should be straight down with the pelvis rolled slightly backwards. This will be your starting position.", "Raise your legs until the torso makes a 90-degree angle with the legs. Exhale as you perform this movement and hold the contraction for a second or so.", "Go back slowly to the starting position as you breathe in.", "Repeat for the recommended amount of repetitions."], "images": ["img/Hanging_Leg_Raise/0.webp", "img/Hanging_Leg_Raise/1.webp"]}, "Incline_Bench_Pull": {"name": "Incline Bench Pull", "equipment": "barbell", "primary": ["middle back"], "instructions": ["Grab a dumbbell in each hand and lie face down on an incline bench that is set to an incline that is approximately 30 degrees.", "Let the arms hang to your sides fully extended as they point to the floor.", "Turn the wrists until your hands have a pronated (palms down) grip.", "Now flare the elbows out. This will be your starting position.", "As you breathe out, start to pull the dumbbells up as if you are doing a reverse bench press. You will do this by bending at the elbows and bringing the upper arms up as you let the forearms hang. Continue this motion until the upper arms are at the same level as your back. Tip: The elbows will come out to the side and your upper arms and torso should make the letter \"T\" at the top of the movement. Hold the contraction at the top for a second.", "Slowly go back down to the starting position as you breathe in.", "Repeat for the recommended amount of repetitions."], "images": ["img/Incline_Bench_Pull/0.webp", "img/Incline_Bench_Pull/1.webp"]}, "Incline_Cable_Flye": {"name": "Incline Cable Flye", "equipment": "cable", "primary": ["chest"], "instructions": ["To get yourself into the starting position, set the pulleys at the floor level (lowest level possible on the machine that is below your torso).", "Place an incline bench (set at 45 degrees) in between the pulleys, select a weight on each one and grab a pulley on each hand.", "With a handle on each hand, lie on the incline bench and bring your hands together at arms length in front of your face. This will be your starting position.", "With a slight bend of your elbows (in order to prevent stress at the biceps tendon), lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary. The movement should only occur at the shoulder joint.", "Return your arms back to the starting position as you squeeze your chest muscles and exhale. Hold the contracted position for a second. Tip: Make sure to use the same arc of motion used to lower the weights.", "Repeat the movement for the prescribed amount of repetitions."], "images": ["img/Incline_Cable_Flye/0.webp", "img/Incline_Cable_Flye/1.webp"]}, "Incline_Dumbbell_Curl": {"name": "Incline Dumbbell Curl", "equipment": "dumbbell", "primary": ["biceps"], "instructions": ["Sit back on an incline bench with a dumbbell in each hand held at arms length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position.", "While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second.", "Slowly begin to bring the dumbbells back to starting position as your breathe in.", "Repeat for the recommended amount of repetitions."], "images": ["img/Incline_Dumbbell_Curl/0.webp", "img/Incline_Dumbbell_Curl/1.webp"]}, "Incline_Dumbbell_Press": {"name": "Incline Dumbbell Press", "equipment": "dumbbell", "primary": ["chest"], "instructions": ["Lie back on an incline bench with a dumbbell in each hand atop your thighs. The palms of your hands will be facing each other.", "Then, using your thighs to help push the dumbbells up, lift the dumbbells one at a time so that you can hold them at shoulder width.", "Once you have the dumbbells raised to shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.", "Be sure to keep full control of the dumbbells at all times. Then breathe out and push the dumbbells up with your chest.", "Lock your arms at the top, hold for a second, and then start slowly lowering the weight. Tip Ideally, lowering the weights should take about twice as long as raising them.", "Repeat the movement for the prescribed amount of repetitions.", "When you are done, place the dumbbells back on your thighs and then on the floor. This is the safest manner to release the dumbbells."], "images": ["img/Incline_Dumbbell_Press/0.webp", "img/Incline_Dumbbell_Press/1.webp"]}, "Lateral_Raise_-_With_Bands": {"name": "Lateral Raise - With Bands", "equipment": "bands", "primary": ["shoulders"], "instructions": ["To begin, stand on an exercise band so that tension begins at arm's length. Grasp the handles using a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The handles should be resting on the sides of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.", "Use your side shoulders to lift the handles to the sides as you exhale. Continue to lift the handles until they are slightly above parallel. Tip: As you lift the handles, slightly tilt the hand as if you were pouring water and keep your arms extended. Also, keep your torso stationary and pause for a second at the top of the movement.", "Lower the handles back down slowly to the starting position. Inhale as you perform this portion of the movement.", "Repeat for the recommended amount of repetitions."], "images": ["img/Lateral_Raise_-_With_Bands/0.webp", "img/Lateral_Raise_-_With_Bands/1.webp"]}, "Leg_Extensions": {"name": "Leg Extensions", "equipment": "machine", "primary": ["quadriceps"], "instructions": ["For this exercise you will need to use a leg extension machine. First choose your weight and sit on the machine with your legs under the pad (feet pointed forward) and the hands holding the side bars. This will be your starting position. Tip: You will need to adjust the pad so that it falls on top of your lower leg (just above your feet). Also, make sure that your legs form a 90-degree angle between the lower and upper leg. If the angle is less than 90-degrees then that means the knee is over the toes which in turn creates undue stress at the knee joint. If the machine is designed that way, either look for another machine or just make sure that when you start executing the exercise you stop going down once you hit the 90-degree angle.", "Using your quadriceps, extend your legs to the maximum as you exhale. Ensure that the rest of the body remains stationary on the seat. Pause a second on the contracted position.", "Slowly lower the weight back to the original position as you inhale, ensuring that you do not go past the 90-degree angle limit.", "Repeat for the recommended amount of times."], "images": ["img/Leg_Extensions/0.webp", "img/Leg_Extensions/1.webp"]}, "Leg_Press": {"name": "Leg Press", "equipment": "machine", "primary": ["quadriceps"], "instructions": ["Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).", "Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you. Tip: Make sure that you do not lock your knees. Your torso and the legs should make a perfect 90-degree angle. This will be your starting position.", "As you inhale, slowly lower the platform until your upper and lower legs make a 90-degree angle.", "Pushing mainly with the heels of your feet and using the quadriceps go back to the starting position as you exhale.", "Repeat for the recommended amount of repetitions and ensure to lock the safety pins properly once you are done. You do not want that platform falling on you fully loaded."], "images": ["img/Leg_Press/0.webp", "img/Leg_Press/1.webp"]}, "Leverage_Decline_Chest_Press": {"name": "Leverage Decline Chest Press", "equipment": "machine", "primary": ["chest"], "instructions": ["Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the bottom of the pectorals at the beginning of the motion. Your chest and head should be up and your shoulder blades retracted. This will be your starting position.", "Press the handles forward by extending through the elbow.", "After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete."], "images": ["img/Leverage_Decline_Chest_Press/0.webp", "img/Leverage_Decline_Chest_Press/1.webp"]}, "Leverage_High_Row": {"name": "Leverage High Row", "equipment": "machine", "primary": ["middle back"], "instructions": ["Load an appropriate weight onto the pins and adjust the seat height so that you can just reach the handles above you. Adjust the knee pad to help keep you down. Grasp the handles with a pronated grip. This will be your starting position.", "Pull the handles towards your torso, retracting your shoulder blades as you flex the elbow.", "Pause at the bottom of the motion, and then slowly return the handles to the starting position.", "For multiple repetitions, avoid completely returning the weight to the stops to keep tension on the muscles being worked."], "images": ["img/Leverage_High_Row/0.webp", "img/Leverage_High_Row/1.webp"]}, "Leverage_Incline_Chest_Press": {"name": "Leverage Incline Chest Press", "equipment": "machine", "primary": ["chest"], "instructions": ["Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the top of the pectorals at the beginning of the motion. Your chest and head should be up and your shoulder blades retracted. This will be your starting position.", "Press the handles forward by extending through the elbow.", "After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete."], "images": ["img/Leverage_Incline_Chest_Press/0.webp", "img/Leverage_Incline_Chest_Press/1.webp"]}, "Leverage_Iso_Row": {"name": "Leverage Iso Row", "equipment": "machine", "primary": ["lats"], "instructions": ["Load an appropriate weight onto the pins and adjust the seat height so that the handles are at chest level. Grasp the handles with either a neutral or pronated grip. This will be your starting position.", "Pull the handles towards your torso, retracting your shoulder blades as you flex the elbow.", "Pause at the bottom of the motion, and then slowly return the handles to the starting position. For multiple repetitions, avoid completely returning the weight to the stops to keep tension on the muscles being worked."], "images": ["img/Leverage_Iso_Row/0.webp", "img/Leverage_Iso_Row/1.webp"]}, "Leverage_Shoulder_Press": {"name": "Leverage Shoulder Press", "equipment": "machine", "primary": ["shoulders"], "instructions": ["Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the top of the shoulders at the beginning of the motion. Your chest and head should be up and handles held with a pronated grip. This will be your starting position.", "Press the handles upward by extending through the elbow.", "After a brief pause at the top, return the weight to just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete."], "images": ["img/Leverage_Shoulder_Press/0.webp", "img/Leverage_Shoulder_Press/1.webp"]}, "Low_Cable_Crossover": {"name": "Low Cable Crossover", "equipment": "cable", "primary": ["chest"], "instructions": ["To move into the starting position, place the pulleys at the low position, select the resistance to be used and grasp a handle in each hand.", "Step forward, gaining tension in the pulleys. Your palms should be facing forward, hands below the waist, and your arms straight. This will be your starting position.", "With a slight bend in your arms, draw your hands upward and toward the midline of your body. Your hands should come together in front of your chest, palms facing up.", "Return your arms back to the starting position after a brief pause."], "images": ["img/Low_Cable_Crossover/0.webp", "img/Low_Cable_Crossover/1.webp"]}, "Low_Cable_Triceps_Extension": {"name": "Low Cable Triceps Extension", "equipment": "cable", "primary": ["triceps"], "instructions": ["Select the desired weight and lay down face up on the bench of a seated row machine that has a rope attached to it. Your head should be pointing towards the attachment.", "Grab the outside of the rope ends with your palms facing each other (neutral grip).", "Position your elbows so that they are bent at a 90 degree angle and your upper arms are perpendicular (90 degree angle) to your torso. Tip: Keep the elbows in and make sure that the upper arms point to the ceiling while your forearms point towards the pulley above your head. This will be your starting position.", "As you breathe out, extend your lower arms until they are straight and vertical. The upper arms and elbows remain stationary throughout the movement. Only the forearms should move. Contract the triceps hard for a second.", "As you breathe in slowly return to the starting position.", "Repeat for the recommended amount of repetitions."], "images": ["img/Low_Cable_Triceps_Extension/0.webp", "img/Low_Cable_Triceps_Extension/1.webp"]}, "Lying_Leg_Curls": {"name": "Lying Leg Curls", "equipment": "machine", "primary": ["hamstrings"], "instructions": ["Adjust the machine lever to fit your height and lie face down on the leg curl machine with the pad of the lever on the back of your legs (just a few inches under the calves). Tip: Preferably use a leg curl machine that is angled as opposed to flat since an angled position is more favorable for hamstrings recruitment.", "Keeping the torso flat on the bench, ensure your legs are fully stretched and grab the side handles of the machine. Position your toes straight (or you can also use any of the other two stances described on the foot positioning section). This will be your starting position.", "As you exhale, curl your legs up as far as possible without lifting the upper legs from the pad. Once you hit the fully contracted position, hold it for a second.", "As you inhale, bring the legs back to the initial position. Repeat for the recommended amount of repetitions."], "images": ["img/Lying_Leg_Curls/0.webp", "img/Lying_Leg_Curls/1.webp"]}, "Lying_Machine_Squat": {"name": "Lying Machine Squat", "equipment": "machine", "primary": ["quadriceps"], "instructions": ["Adjust the leg machine to a height that will allow you to get inside it with your knees bent and the thighs slightly below parallel.", "Once you select the weight, position yourself inside the machine face up with the knees bent and thighs slightly below parallel to the platform. Make sure that the knees do not go past the toes. The angle created between the hamstrings and the calves should be one that is slightly less than 90 degrees (since your starting position requires you to start slightly below parallel). Your back and your head should be resting on the machine while your shoulders are pressed under the shoulder pads.", "Place your hands by the handles and position your feet slightly pointing out at a shoulder width position. This will be your starting position.", "While pressing with the balls of the feet as you breathe out, make your whole body erect as you squeeze the quads. Hold the contracted position for a second. Tip: Since you are starting below parallel, you can opt to use your hands to help you up by pressing on your thighs only on the first repetition.", "Slowly squat down as you inhale but instead of going all the way down to the starting position, just stop once your thighs are parallel to the platform. The angle between your hamstrings and calves should be a 90-degree angle.", "Repeat for the recommended amount of repetitions."], "images": ["img/Lying_Machine_Squat/0.webp", "img/Lying_Machine_Squat/1.webp"]}, "Lying_One-Arm_Lateral_Raise": {"name": "Lying One-Arm Lateral Raise", "equipment": "dumbbell", "primary": ["shoulders"], "instructions": ["While holding a dumbbell in one hand, lay with your chest down on a flat bench. The other hand can be used to hold to the leg of the bench for stability.", "Position the palm of the hand that is holding the dumbbell in a neutral manner (palms facing your torso) as you keep the arm extended with the elbow slightly bent. This will be your starting position.", "Now raise the arm with the dumbbell to the side until your elbow is at shoulder height and your arm is roughly parallel to the floor as you exhale. Tip: Maintain your arm perpendicular to the torso while keeping your arm extended throughout the movement. Also, keep the contraction at the top for a second.", "Slowly lower the dumbbell to the starting position as you inhale.", "Repeat for the recommended amount of repetitions."], "images": ["img/Lying_One-Arm_Lateral_Raise/0.webp", "img/Lying_One-Arm_Lateral_Raise/1.webp"]}, "Lying_T-Bar_Row": {"name": "Lying T-Bar Row", "equipment": "machine", "primary": ["middle back"], "instructions": ["Load up the T-bar Row Machine with the desired weight and adjust the leg height so that your upper chest is at the top of the pad. Tip: In some machines all you can do is stand on the appropriate step that allows you to be at a height that has the upper chest at the top of the pad.", "Lay face down on the pad and grab the handles. You can either use a palms down, palms up, or palms in position depending on what part of your back you want to emphasize.", "Lift the bar off the rack and extend your arms in front of you. This will be your starting position.", "As you exhale slowly pull the weight up and squeeze your back at the top of the movement. Tip: Keep the upper arms as close to the torso as possible throughout the movement in order to better engage the back muscles. Also, do not lift your body off of the pad at any time and refrain from using the biceps to lift the weight.", "After a second contraction at the top of the movement, as you inhale, slowly go back down to the starting position.", "Repeat for the recommended amount of repetitions."], "images": ["img/Lying_T-Bar_Row/0.webp", "img/Lying_T-Bar_Row/1.webp"]}, "Lying_Triceps_Press": {"name": "Lying Triceps Press", "equipment": "e-z curl bar", "primary": ["triceps"], "instructions": ["Lie on a flat bench with either an e-z bar (my preference) or a straight bar placed on the floor behind your head and your feet on the floor.", "Grab the bar behind you, using a medium overhand (pronated) grip, and raise the bar in front of you at arms length. Tip: The arms should be perpendicular to the torso and the floor. The elbows should be tucked in. This is the starting position.", "As you breathe in, slowly lower the weight until the bar lightly touches your forehead while keeping the upper arms and elbows stationary.", "At that point, use the triceps to bring the weight back up to the starting position as you breathe out.", "Repeat for the recommended amount of repetitions."], "images": ["img/Lying_Triceps_Press/0.webp", "img/Lying_Triceps_Press/1.webp"]}, "Machine_Bench_Press": {"name": "Machine Bench Press", "equipment": "machine", "primary": ["chest"], "instructions": ["Sit down on the Chest Press Machine and select the weight.", "Step on the lever provided by the machine since it will help you to bring the handles forward so that you can grab the handles and fully extend the arms.", "Grab the handles with a palms-down grip and lift your elbows so that your upper arms are parallel to the floor to the sides of your torso. Tip: Your forearms will be pointing forward since you are grabbing the handles. Once you bring the handles forward and extend the arms you will be at the starting position.", "Now bring the handles back towards you as you breathe in.", "Push the handles away from you as you flex your pecs and you breathe out. Hold the contraction for a second before going back to the starting position.", "Repeat for the recommended amount of reps.", "When finished step on the lever again and slowly get the handles back to their original place."], "images": ["img/Machine_Bench_Press/0.webp", "img/Machine_Bench_Press/1.webp"]}, "Machine_Preacher_Curls": {"name": "Machine Preacher Curls", "equipment": "machine", "primary": ["biceps"], "instructions": ["Sit down on the Preacher Curl Machine and select the weight.", "Place the back of your upper arms (your triceps) on the preacher pad provided and grab the handles using an underhand grip (palms facing up). Tip: Make sure that when you place the arms on the pad you keep the elbows in. This will be your starting position.", "Now lift the handles as you exhale and you contract the biceps. At the top of the position make sure that you hold the contraction for a second. Tip: Only the forearms should move. The upper arms should remain stationary and on the pad at all times.", "Lower the handles slowly back to the starting position as you inhale.", "Repeat for the recommended amount of repetitions."], "images": ["img/Machine_Preacher_Curls/0.webp", "img/Machine_Preacher_Curls/1.webp"]}, "Narrow_Stance_Leg_Press": {"name": "Narrow Stance Leg Press", "equipment": "machine", "primary": ["quadriceps"], "instructions": ["Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a less-than-shoulder-width narrow stance with the toes slightly pointed out. Your feet should be around 3 inches or less apart. Tip: Keep your head up at all times and also maintain the back on the pad at all times.", "Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you. Tip: Make sure that you do not lock your knees. Your torso and the legs should make a perfect 90-degree angle. This will be your starting position.", "As you inhale, slowly lower the platform until your upper and lower legs make a 90-degree angle.", "Pushing mainly with the heels of your feet and using the quadriceps go back to the starting position as you exhale.", "Repeat for the recommended amount of repetitions and ensure to lock the safety pins properly once you are done. You do not want that platform falling on you fully loaded."], "images": ["img/Narrow_Stance_Leg_Press/0.webp", "img/Narrow_Stance_Leg_Press/1.webp"]}, "One-Arm_Incline_Lateral_Raise": {"name": "One-Arm Incline Lateral Raise", "equipment": "dumbbell", "primary": ["shoulders"], "instructions": ["Lie down sideways on an incline bench press with a dumbbell in the hand. Make sure the shoulder is pressing against the incline bench and the arm is lying across your body with the palm around your navel.", "Hold a dumbbell in your uppermost arm while keeping it extended in front of you parallel to the floor. This is your starting position.", "While keeping the dumbbell parallel to the floor at all times, perform a lateral raise. Your arm should travel straight up until it is pointing at the ceiling. Tip: Exhale as you perform this movement. Hold the dumbbell in the position and feel the contraction in the shoulders for a second.", "While inhaling lower the weight across your body back into the starting position.", "Repeat the movement for the prescribed amount of repetitions.", "Switch arms and repeat the movement."], "images": ["img/One-Arm_Incline_Lateral_Raise/0.webp", "img/One-Arm_Incline_Lateral_Raise/1.webp"]}, "Overhead_Cable_Curl": {"name": "Overhead Cable Curl", "equipment": "cable", "primary": ["biceps"], "instructions": ["To begin, set a weight that is comfortable on each side of the pulley machine. Note: Make sure that the amount of weight selected is the same on each side.", "Now adjust the height of the pulleys on each side and make sure that they are positioned at a height higher than that of your shoulders.", "Stand in the middle of both sides and use an underhand grip (palms facing towards the ceiling) to grab each handle. Your arms should be fully extended and parallel to the floor with your feet positioned shoulder width apart from each other. Your body should be evenly aligned the handles. This is the starting position.", "While exhaling, slowly squeeze the biceps on each side until your forearms and biceps touch.", "While inhaling, move your forearms back to the starting position. Note: Your entire body is stationary during this exercise except for the forearms.", "Repeat for the recommended amount of repetitions prescribed in your program."], "images": ["img/Overhead_Cable_Curl/0.webp", "img/Overhead_Cable_Curl/1.webp"]}, "Pallof_Press": {"name": "Pallof Press", "equipment": "cable", "primary": ["abdominals"], "instructions": ["Connect a standard handle to a tower, and—if possible—position the cable to shoulder height. If not, a low pulley will suffice.", "With your side to the cable, grab the handle with both hands and step away from the tower. You should be approximately arm's length away from the pulley, with the tension of the weight on the cable.", "With your feet positioned hip-width apart and knees slightly bent, hold the cable to the middle of your chest. This will be your starting position.", "Press the cable away from your chest, fully extending both arms. You core should be tight and engaged.", "Hold the repetition for several seconds before returning to the starting position.", "At the conclusion of the set, repeat facing the other direction."], "images": ["img/Pallof_Press/0.webp", "img/Pallof_Press/1.webp"]}, "Plank": {"name": "Plank", "equipment": "body only", "primary": ["abdominals"], "instructions": ["Get into a prone position on the floor, supporting your weight on your toes and your forearms. Your arms are bent and directly below the shoulder.", "Keep your body straight at all times, and hold this position as long as possible. To increase difficulty, an arm or leg can be raised."], "images": ["img/Plank/0.webp", "img/Plank/1.webp"]}, "Preacher_Curl": {"name": "Preacher Curl", "equipment": "barbell", "primary": ["biceps"], "instructions": ["To perform this movement you will need a preacher bench and an E-Z bar. Grab the E-Z curl bar at the close inner handle (either have someone hand you the bar which is preferable or grab the bar from the front bar rest provided by most preacher benches). The palm of your hands should be facing forward and they should be slightly tilted inwards due to the shape of the bar.", "With the upper arms positioned against the preacher bench pad and the chest against it, hold the E-Z Curl Bar at shoulder length. This will be your starting position.", "As you breathe in, slowly lower the bar until your upper arm is extended and the biceps is fully stretched.", "As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the bar is at shoulder height. Squeeze the biceps hard and hold this position for a second.", "Repeat for the recommended amount of repetitions."], "images": ["img/Preacher_Curl/0.webp", "img/Preacher_Curl/1.webp"]}, "Pullups": {"name": "Pullups", "equipment": "body only", "primary": ["lats"], "instructions": ["Grab the pull-up bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.", "As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.", "Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.", "After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.", "Repeat this motion for the prescribed amount of repetitions."], "images": ["img/Pullups/0.webp", "img/Pullups/1.webp"]}, "Reverse_Flyes": {"name": "Reverse Flyes", "equipment": "dumbbell", "primary": ["shoulders"], "instructions": ["To begin, lie down on an incline bench with the chest and stomach pressing against the incline. Have the dumbbells in each hand with the palms facing each other (neutral grip).", "Extend the arms in front of you so that they are perpendicular to the angle of the bench. The legs should be stationary while applying pressure with the ball of your toes. This is the starting position.", "Maintaining the slight bend of the elbows, move the weights out and away from each other (to the side) in an arc motion while exhaling. Tip: Try to squeeze your shoulder blades together to get the best results from this exercise.", "The arms should be elevated until they are parallel to the floor.", "Feel the contraction and slowly lower the weights back down to the starting position while inhaling.", "Repeat for the recommended amount of repetitions."], "images": ["img/Reverse_Flyes/0.webp", "img/Reverse_Flyes/1.webp"]}, "Reverse_Flyes_With_External_Rotation": {"name": "Reverse Flyes With External Rotation", "equipment": "dumbbell", "primary": ["shoulders"], "instructions": ["To begin, lie down on an incline bench set at a 30-degree angle with the chest and stomach pressing against the incline.", "Have the dumbbells in each hand with the palms facing down to the floor. Your arms should be in front of you so that they are perpendicular to the angle of the bench. Tip: Your elbows should have a slight bend. The legs should be stationary while applying pressure with the ball of your toes (your heels should not be touching the floor). This is the starting position.", "Maintaining the slight bend of the elbows, move the weights out and away from each other in an arc motion while exhaling.", "As you lift the weight, your wrist should externally rotate by 90-degrees so that you go from a palms down (pronated) grip to a palms facing each other (neutral) grip. Tip: Try to squeeze your shoulder blades together to get the best results from this exercise.", "The arms should be elevated until they are level with the head.", "Feel the contraction and slowly lower the weights back down to the starting position while inhaling.", "Repeat for the recommended amount of repetitions."], "images": ["img/Reverse_Flyes_With_External_Rotation/0.webp", "img/Reverse_Flyes_With_External_Rotation/1.webp"]}, "Reverse_Machine_Flyes": {"name": "Reverse Machine Flyes", "equipment": "machine", "primary": ["shoulders"], "instructions": ["Adjust the handles so that they are fully to the rear. Make an appropriate weight selection and adjust the seat height so the handles are at shoulder level. Grasp the handles with your hands facing inwards. This will be your starting position.", "In a semicircular motion, pull your hands out to your side and back, contracting your rear delts.", "Keep your arms slightly bent throughout the movement, with all of the motion occurring at the shoulder joint.", "Pause at the rear of the movement, and slowly return the weight to the starting position."], "images": ["img/Reverse_Machine_Flyes/0.webp", "img/Reverse_Machine_Flyes/1.webp"]}, "Romanian_Deadlift": {"name": "Romanian Deadlift", "equipment": "barbell", "primary": ["hamstrings"], "instructions": ["Put a barbell in front of you on the ground and grab it using a pronated (palms facing down) grip that a little wider than shoulder width. Tip: Depending on the weight used, you may need wrist wraps to perform the exercise and also a raised platform in order to allow for better range of motion.", "Bend the knees slightly and keep the shins vertical, hips back and back straight. This will be your starting position.", "Keeping your back and arms completely straight at all times, use your hips to lift the bar as you exhale. Tip: The movement should not be fast but steady and under control.", "Once you are standing completely straight up, lower the bar by pushing the hips back, only slightly bending the knees, unlike when squatting. Tip: Take a deep breath at the start of the movement and keep your chest up. Hold your breath as you lower and exhale as you complete the movement.", "Repeat for the recommended amount of repetitions."], "images": ["img/Romanian_Deadlift/0.webp", "img/Romanian_Deadlift/1.webp"]}, "Seated_Cable_Rows": {"name": "Seated Cable Rows", "equipment": "cable", "primary": ["middle back"], "instructions": ["For this exercise you will need access to a low pulley row machine with a V-bar. Note: The V-bar will enable you to have a neutral grip where the palms of your hands face each other. To get into the starting position, first sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.", "Lean over as you keep the natural alignment of your back and grab the V-bar handles.", "With your arms extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lats as you hold the bar in front of you. This is the starting position of the exercise.", "Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it until you touch the abdominals. Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard. Hold that contraction for a second and slowly go back to the original position while breathing in.", "Repeat for the recommended amount of repetitions."], "images": ["img/Seated_Cable_Rows/0.webp", "img/Seated_Cable_Rows/1.webp"]}, "Seated_Calf_Raise": {"name": "Seated Calf Raise", "equipment": "machine", "primary": ["calves"], "instructions": ["Sit on the machine and place your toes on the lower portion of the platform provided with the heels extending off. Choose the toe positioning of your choice (forward, in, or out) as per the beginning of this chapter.", "Place your lower thighs under the lever pad, which will need to be adjusted according to the height of your thighs. Now place your hands on top of the lever pad in order to prevent it from slipping forward.", "Lift the lever slightly by pushing your heels up and release the safety bar. This will be your starting position.", "Slowly lower your heels by bending at the ankles until the calves are fully stretched. Inhale as you perform this movement.", "Raise the heels by extending the ankles as high as possible as you contract the calves and breathe out. Hold the top contraction for a second.", "Repeat for the recommended amount of repetitions."], "images": ["img/Seated_Calf_Raise/0.webp", "img/Seated_Calf_Raise/1.webp"]}, "Seated_Dumbbell_Press": {"name": "Seated Dumbbell Press", "equipment": "dumbbell", "primary": ["shoulders"], "instructions": ["Grab a couple of dumbbells and sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs.", "Clean the dumbbells up one at a time by using your thighs to bring the dumbbells up to shoulder height at each side.", "Rotate the wrists so that the palms of your hands are facing forward. This is your starting position.", "As you exhale, push the dumbbells up until they touch at the top.", "After a second pause, slowly come down back to the starting position as you inhale.", "Repeat for the recommended amount of repetitions."], "images": ["img/Seated_Dumbbell_Press/0.webp", "img/Seated_Dumbbell_Press/1.webp"]}, "Seated_Leg_Curl": {"name": "Seated Leg Curl", "equipment": "machine", "primary": ["hamstrings"], "instructions": ["Adjust the machine lever to fit your height and sit on the machine with your back against the back support pad.", "Place the back of lower leg on top of padded lever (just a few inches under the calves) and secure the lap pad against your thighs, just above the knees. Then grasp the side handles on the machine as you point your toes straight (or you can also use any of the other two stances) and ensure that the legs are fully straight right in front of you. This will be your starting position.", "As you exhale, pull the machine lever as far as possible to the back of your thighs by flexing at the knees. Keep your torso stationary at all times. Hold the contracted position for a second.", "Slowly return to the starting position as you breathe in.", "Repeat for the recommended amount of repetitions."], "images": ["img/Seated_Leg_Curl/0.webp", "img/Seated_Leg_Curl/1.webp"]}, "Side_Lateral_Raise": {"name": "Side Lateral Raise", "equipment": "dumbbell", "primary": ["shoulders"], "instructions": ["Pick a couple of dumbbells and stand with a straight torso and the dumbbells by your side at arms length with the palms of the hand facing you. This will be your starting position.", "While maintaining the torso in a stationary position (no swinging), lift the dumbbells to your side with a slight bend on the elbow and the hands slightly tilted forward as if pouring water in a glass. Continue to go up until you arms are parallel to the floor. Exhale as you execute this movement and pause for a second at the top.", "Lower the dumbbells back down slowly to the starting position as you inhale.", "Repeat for the recommended amount of repetitions."], "images": ["img/Side_Lateral_Raise/0.webp", "img/Side_Lateral_Raise/1.webp"]}, "Single-Leg_Leg_Extension": {"name": "Single-Leg Leg Extension", "equipment": "machine", "primary": ["quadriceps"], "instructions": ["Seat yourself in the machine and adjust it so that you are positioned properly. The pad should be against the lower part of the shin but not in contact with the ankle. Adjust the seat so that the pivot point is in line with your knee. Select a weight appropriate for your abilities.", "Maintaining good posture, fully extend one leg, pausing at the top of the motion.", "Return to the starting position without letting the weight stop, keeping tension on the muscle.", "Repeat for the desired number of repetitions."], "images": ["img/Single-Leg_Leg_Extension/0.webp", "img/Single-Leg_Leg_Extension/1.webp"]}, "Single_Leg_Glute_Bridge": {"name": "Single Leg Glute Bridge", "equipment": "body only", "primary": ["glutes"], "instructions": ["Lay on the floor with your feet flat and knees bent.", "Raise one leg off of the ground, pulling the knee to your chest. This will be your starting position.", "Execute the movement by driving through the heel, extending your hip upward and raising your glutes off of the ground.", "Extend as far as possible, pause and then return to the starting position."], "images": ["img/Single_Leg_Glute_Bridge/0.webp", "img/Single_Leg_Glute_Bridge/1.webp"]}, "Smith_Machine_Bench_Press": {"name": "Smith Machine Bench Press", "equipment": "machine", "primary": ["chest"], "instructions": ["Place a flat bench underneath the smith machine. Now place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the flat bench. Using a pronated grip that is wider than shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.", "As you breathe in, come down slowly until you feel the bar on your middle chest.", "After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.", "Repeat the movement for the prescribed amount of repetitions.", "When you are done, lock the bar back in the rack."], "images": ["img/Smith_Machine_Bench_Press/0.webp", "img/Smith_Machine_Bench_Press/1.webp"]}, "Smith_Machine_Calf_Raise": {"name": "Smith Machine Calf Raise", "equipment": "machine", "primary": ["calves"], "instructions": ["Place a block or weight plate below the bar on the Smith machine. Set the bar to a position that best matches your height. Once the correct height is chosen and the bar is loaded, step onto the plates with the balls of your feet and place the bar on the back of your shoulders.", "Take the bar with both hands facing forward. Rotate the bar to unrack it. This will be your starting position.", "Raise your heels as high as possible by pushing off of the balls of your feet, flexing your calf at the top of the contraction. Your knees should remain extended. Hold the contracted position for a second before you start to go back down.", "Return slowly to the starting position as you breathe in while lowering your heels.", "Repeat for the recommended amount of repetitions."], "images": ["img/Smith_Machine_Calf_Raise/0.webp", "img/Smith_Machine_Calf_Raise/1.webp"]}, "Smith_Machine_Leg_Press": {"name": "Smith Machine Leg Press", "equipment": "machine", "primary": ["quadriceps"], "instructions": ["Position a Smith machine bar a couple feet off of the ground. Ensure that it is resting on the safeties. After loading the bar to an appropriate weight, lie underneath the bar. Place the middle of your feet on the bar, tucking your knees to your chest. This will be your starting position.", "Begin the movement by driving through your feet to move the bar upward, extending the hips and knees. Do not lock out your knees.", "At the top of the motion, pause briefly before returning to the starting position."], "images": ["img/Smith_Machine_Leg_Press/0.webp", "img/Smith_Machine_Leg_Press/1.webp"]}, "Smith_Single-Leg_Split_Squat": {"name": "Smith Single-Leg Split Squat", "equipment": "machine", "primary": ["quadriceps"], "instructions": ["To begin, place a flat bench 2-3 feet behind the smith machine. Then, set the bar on the height that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.", "Hold on to the bar using both arms at each side (palms facing forward), unlock it and lift it off the rack by first pushing with your legs and at the same time straightening your torso.", "Position your legs by placing one foot slightly forward under the bar and extending your other leg back and place the top of your foot on the bench. This will be your starting position", "Begin to slowly lower the bar by bending the knee as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calf becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knee should make an imaginary straight line with the toes that is perpendicular to the front. If your knee is past that imaginary line (if it is past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.", "Begin to raise the bar as you exhale by pushing the floor with the heel of your foot mainly as you straighten your leg again and go back to the starting position.", "Repeat for the recommended amount of repetitions.", "Switch legs and repeat the movement."], "images": ["img/Smith_Single-Leg_Split_Squat/0.webp", "img/Smith_Single-Leg_Split_Squat/1.webp"]}, "Split_Squat_with_Dumbbells": {"name": "Split Squat with Dumbbells", "equipment": "dumbbell", "primary": ["quadriceps"], "instructions": ["Position yourself into a staggered stance with the rear foot elevated and front foot forward.", "Hold a dumbbell in each hand, letting them hang at the sides. This will be your starting position.", "Begin by descending, flexing your knee and hip to lower your body down. Maintain good posture througout the movement. Keep the front knee in line with the foot as you perform the exercise.", "At the bottom of the movement, drive through the heel to extend the knee and hip to return to the starting position."], "images": ["img/Split_Squat_with_Dumbbells/0.webp", "img/Split_Squat_with_Dumbbells/1.webp"]}, "Standing_Calf_Raises": {"name": "Standing Calf Raises", "equipment": "machine", "primary": ["calves"], "instructions": ["Adjust the padded lever of the calf raise machine to fit your height.", "Place your shoulders under the pads provided and position your toes facing forward (or using any of the two other positions described at the beginning of the chapter). The balls of your feet should be secured on top of the calf block with the heels extending off it. Push the lever up by extending your hips and knees until your torso is standing erect. The knees should be kept with a slight bend; never locked. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. This will be your starting position.", "Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.", "Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.", "Repeat for the recommended amount of repetitions."], "images": ["img/Standing_Calf_Raises/0.webp", "img/Standing_Calf_Raises/1.webp"]}, "Standing_Leg_Curl": {"name": "Standing Leg Curl", "equipment": "machine", "primary": ["hamstrings"], "instructions": ["Adjust the machine lever to fit your height and lie with your torso bent at the waist facing forward around 30-45 degrees (since an angled position is more favorable for hamstrings recruitment) with the pad of the lever on the back of your right leg (just a few inches under the calves) and the front of the right leg on top of the machine pad.", "Keeping the torso bent forward, ensure your leg is fully stretched and grab the side handles of the machine. Position your toes straight. This will be your starting position.", "As you exhale, curl your right leg up as far as possible without lifting the upper leg from the pad. Once you hit the fully contracted position, hold it for a second.", "As you inhale, bring the legs back to the initial position. Repeat for the recommended amount of repetitions.", "Perform the same exercise now for the left leg."], "images": ["img/Standing_Leg_Curl/0.webp", "img/Standing_Leg_Curl/1.webp"]}, "Stiff_Leg_Barbell_Good_Morning": {"name": "Stiff Leg Barbell Good Morning", "equipment": "barbell", "primary": ["lower back"], "instructions": ["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.", "Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.", "Step away from the rack and position your legs using a shoulder width medium stance. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position.", "Keeping your legs stationary, move your torso forward by bending at the hips while inhaling. Lower your torso until it is parallel with the floor.", "Begin to raise the bar as you exhale by elevating your torso back to the starting position.", "Repeat for the recommended amount of repetitions."], "images": ["img/Stiff_Leg_Barbell_Good_Morning/0.webp", "img/Stiff_Leg_Barbell_Good_Morning/1.webp"]}, "V-Bar_Pulldown": {"name": "V-Bar Pulldown", "equipment": "cable", "primary": ["lats"], "instructions": ["Sit down on a pull-down machine with a V-Bar attached to the top pulley.", "Adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.", "Grab the V-bar with the palms facing each other (a neutral grip). Stick your chest out and lean yourself back slightly (around 30-degrees) in order to better engage the lats. This will be your starting position.", "Using your lats, pull the bar down as you squeeze your shoulder blades. Continue until your chest nearly touches the V-bar. Exhale as you execute this motion. Tip: Keep the torso stationary throughout the movement.", "After a second hold on the contracted position, slowly bring the bar back to the starting position as you breathe in.", "Repeat for the prescribed number of repetitions."], "images": ["img/V-Bar_Pulldown/0.webp", "img/V-Bar_Pulldown/1.webp"]}, "Wide-Grip_Lat_Pulldown": {"name": "Wide-Grip Lat Pulldown", "equipment": "cable", "primary": ["lats"], "instructions": ["Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.", "Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.", "As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.", "As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the bar; therefore do not try to pull down the bar using the forearms.", "After a second at the contracted position squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.", "Repeat this motion for the prescribed amount of repetitions."], "images": ["img/Wide-Grip_Lat_Pulldown/0.webp", "img/Wide-Grip_Lat_Pulldown/1.webp"]}};
